import type { Icon } from '@phosphor-icons/react';
import { Buildings, Cube, CubeTransparent, Eye, Image, Mountains, Stack, Scissors } from '@phosphor-icons/react';

export type ToolId =
  | 'osgb-convert'
  | 'model-convert'
  | 'ifc-convert'
  | 'terrain-tile'
  | 'tiles-preview'
  | 'tiles-rebuild'
  | 'tiles-texture'
  | 'tiles-merge'
  | 'tiles-clip';

export type ToolDef = {
  id: ToolId;
  title: string;
  desc: string;
  to: string;
  icon: Icon;
};

export type ToolGroup = {
  id: string;
  title: string;
  tools: ToolDef[];
};

export const toolGroups: ToolGroup[] = [
  {
    id: 'oblique',
    title: '转换',
    tools: [
      {
        id: 'osgb-convert',
        title: 'OSGB 转换',
        desc: '将 OSGB 数据转换为 3D Tiles',
        to: '/osgb/convert',
        icon: Stack,
      },
      {
        id: 'model-convert',
        title: '通用模型转换',
        desc: '将 FBX 或 OBJ 模型转换为 3D Tiles',
        to: '/model/convert',
        icon: CubeTransparent,
      },
      {
        id: 'ifc-convert',
        title: 'IFC 转换',
        desc: '将 IFC 建筑模型转换为带构件属性的 3D Tiles',
        to: '/ifc/convert',
        icon: Buildings,
      },
    ],
  },
  {
    id: 'terrain',
    title: '地形',
    tools: [
      {
        id: 'terrain-tile',
        title: '地形切片',
        desc: '将 DEM 切成 Cesium quantized-mesh 地形',
        to: '/terrain/tile',
        icon: Mountains,
      },
    ],
  },
  {
    id: 'tiles',
    title: '3D Tiles',
    tools: [
      {
        id: 'tiles-merge',
        title: '3D Tiles 合并',
        desc: '将多份 Tileset 合并为统一成果',
        to: '/tiles/merge',
        icon: Stack,
      },
      {
        id: 'tiles-clip',
        title: '范围裁剪',
        desc: '精确保留指定地理区域内的模型',
        to: '/tiles/clip',
        icon: Scissors,
      },
      {
        id: 'tiles-preview',
        title: '预览与编辑',
        desc: '浏览模型，绘制区域并裁剪或压平',
        to: '/preview/tiles',
        icon: Eye,
      },
      {
        id: 'tiles-rebuild',
        title: '顶层重建',
        desc: '重建 3D Tiles 的顶层结构',
        to: '/tiles/process?op=rebuild',
        icon: Cube,
      },
      {
        id: 'tiles-texture',
        title: '纹理压缩',
        desc: '压缩 3D Tiles 纹理以减小体积',
        to: '/tiles/process?op=texture',
        icon: Image,
      },
    ],
  },
];

export function filterToolGroups(query: string): ToolGroup[] {
  const q = query.trim().toLowerCase();
  if (!q) return toolGroups;
  return toolGroups
    .map((g) => ({
      ...g,
      tools: g.tools.filter(
        (t) => t.title.toLowerCase().includes(q) || t.desc.toLowerCase().includes(q),
      ),
    }))
    .filter((g) => g.tools.length > 0);
}
